  taskList.innerHTML = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === task.completed).map(task => `<div class="row" data-testid="task-row"><span>${escapeHtml(task.title)}</span><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''} data-task-id="${task.id}"></div>`).join('');
  taskList.querySelectorAll('input[type=checkbox]').forEach(box => box.addEventListener('change', async () => {
    await fetch(`/api/tasks/${box.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) });
    await refreshTasks();
  }));
}
filter.addEventListener('change', refreshTasks);
taskForm.addEventListener('submit', async event => {
  event.preventDefault();
  taskError.hidden = true;
  const response = await fetch(`/api/projects/${project.id}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: taskInput.value }) });
