edits.newText:
app.innerHTML = `<button id="back">Projects</button><h1>${escapeHtml(project.name)}</h1>
  <form id="task-form"><input id="task-title" aria-label="Task title" placeholder="Task title"><button type="submit">Create task</button></form>
  <p class="error" role="alert" hidden></p>
  <label for="task-filter">Task filter</label> <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
  <section id="tasks" aria-label="Tasks"></section>`;
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskError = document.querySelector('.error');
const taskList = document.querySelector('#tasks');
const filter = document.querySelector('#task-filter');
async function refreshTasks() {
  const tasks = await fetch(`/api/projects/${project.id}/tasks`).then(response => response.json());
  taskList.innerHTML = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === task.completed).map(task => `<div class="row" data-testid="task-row"><span>${escapeHtml(task.title)}</span><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''} data-task-id="${task.id}"></div>`).join('');
  taskList.querySelectorAll('input[type=checkbox]').forEach(box => box.addEventListener('change', async () => {
    await fetch(`/api/tasks/${box.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) });
    await refreshTasks();
  }));
}
filter.addEventListener('change', refreshTasks);
taskForm.addEventListener('submit', async event => {
  event.preventDefault();
  taskError.hidden = true;
  const response = await fetch(`/api/projects/${project.id}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: taskInput.value }) });
  const result = await response.json();
  if (!response.ok) { taskError.textContent = result.error; taskError.hidden = false; return; }
  taskInput.value = '';
  await refreshTasks();
});
await refreshTasks();

